'use client'

import { useEffect, useState } from 'react'

type DashboardData = {
  analytics: unknown
  notifications: unknown
  settings: unknown
}

export default function Dashboard() {
  const [data, setData] = useState<DashboardData | null>(null)
  const [error, setError] = useState(false)

  useEffect(() => {
    const controller = new AbortController()

    async function fetchData(url: string) {
      const response = await fetch(url, { signal: controller.signal })
      if (!response.ok) throw new Error(`Failed to fetch ${url}`)
      return response.json()
    }

    async function loadDashboard() {
      try {
        const [analytics, notifications, settings] = await Promise.all([
          fetchData('/api/analytics'),
          fetchData('/api/notifications'),
          fetchData('/api/settings'),
        ])
        if (!controller.signal.aborted) {
          setData({ analytics, notifications, settings })
        }
      } catch {
        if (!controller.signal.aborted) setError(true)
      }
    }

    void loadDashboard()
    return () => controller.abort()
  }, [])

  return (
    <div>
      <h2>Dashboard Content</h2>
      {error ? (
        <p role="alert">Failed to load dashboard data.</p>
      ) : data ? (
        <>
          <section>
            <h3>Analytics</h3>
            <pre>{JSON.stringify(data.analytics, null, 2)}</pre>
          </section>
          <section>
            <h3>Notifications</h3>
            <pre>{JSON.stringify(data.notifications, null, 2)}</pre>
          </section>
          <section>
            <h3>Settings</h3>
            <pre>{JSON.stringify(data.settings, null, 2)}</pre>
          </section>
        </>
      ) : (
        <p>Loading dashboard data...</p>
      )}
    </div>
  )
}

